function average(a) {
  let sum = 0;
  for (let i = 0; i < a.length; i++) {
    sum += a[i];
  }
  return sum / a.length;
}

const marks = [45, 72, 90, 38];
console.log(average(marks));
console.log(marks.filter(function (m) { return m >= 60; }).join(','));
console.log(marks.map(function (m) { return m + 5; }).join(','));
